contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a)); require(a <= 1000000000000000000000000000000);
        require(a > 0);
        require(address(this).balance >= a);

        c.deposit{value: a}(); if (__ESBMC_reverted()) return;
        c.refund(); if (__ESBMC_reverted()) return;

        bool revertedW;
        c.withdraw(1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedW = true; } else { revertedW = false; }

        assert(revertedW);
    }

    receive() external payable {}
}

